(6852098, 1031159, 30982, '<td valign="top">A good street portrait of a colorful character.</td>', 'A good street portrait of a colorful character.', '2012-08-30 00:52:51.000000', NULL, 1),
(6852100, 1031267, 30982, '<td valign="top">Lots of colorful action.  Sun may be a bit bright this time of day and it is a tad busy (which is often the case with street photography!)</td>', 'Lots of colorful action.  Sun may be a bit bright this time of day and it is a tad busy (which is often the case with street photography!)', '2012-08-30 00:53:26.000000', NULL, 1),
(6852101, 1031302, 30982, '<td valign="top">Love the slants of light falling across.</td>', 'Love the slants of light falling across.', '2012-08-30 00:53:53.000000', NULL, 1),
(6852102, 1031085, 30982, '<td valign="top">Not a very romantic backdrop for a kiss!</td>', 'Not a very romantic backdrop for a kiss!', '2012-08-30 00:54:31.000000', NULL, 1),
(6852103, 1031217, 30982, '<td valign="top">Now there''s truth in advertising....</td>', 'Now there''s truth in advertising....', '2012-08-30 00:54:48.000000', NULL, 1),
(6852104, 1031214, 30982, '<td valign="top">One wonders if he has car trouble and is looking to get a lift.  But one also wonders why he chose to stand in front of a puddle...  Nice for the reflective aspect, though!</td>', 'One wonders if he has car trouble and is looking to get a lift.  But one also wonders why he chose to stand in front of a puddle...  Nice for the reflective aspect, though!', '2012-08-30 00:55:26.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6852106, 1030785, 30982, '<td valign="top">Interesting expressions and a good "street" backdrop.  You might try cropping the left side to the wall to have a bit cleaner framing.</td>', 'Interesting expressions and a good "street" backdrop.  You might try cropping the left side to the wall to have a bit cleaner framing.', '2012-08-30 01:01:38.000000', NULL, 1),
(6852107, 1031007, 30982, '<td valign="top">Makes me curious what she''s got there...  I also like the other kids in the reflection.</td>', 'Makes me curious what she''s got there...  I also like the other kids in the reflection.', '2012-08-30 01:02:12.000000', NULL, 1),
(6852108, 1031161, 30982, '<td valign="top">Nice natural framing for this.</td>', 'Nice natural framing for this.', '2012-08-30 01:02:22.000000', NULL, 1),
(6852109, 1030753, 30982, '<td valign="top">I get the impression it''s a very upscale resort and he''s doing a bit of gardening.  Nice toning.</td>', 'I get the impression it''s a very upscale resort and he''s doing a bit of gardening.  Nice toning.', '2012-08-30 01:02:45.000000', NULL, 1),
(6852110, 1031191, 30982, '<td valign="top">Cute and a little shy!</td>', 'Cute and a little shy!', '2012-08-30 01:04:06.000000', NULL, 1),
(6852111, 1031168, 30982, '<td valign="top">Love the vibrance of the color!  Interesting choice to desat the background.  In this case it probably does serve to showcase the color where you want it.</td>', 'Love the vibrance of the color!  Interesting choice to desat the background.  In this case it probably does serve to showcase the color where you want it.', '2012-08-30 01:04:52.000000', NULL, 1),
(6852112, 1031177, 30982, '<td valign="top">LOL!  Gotta love those expressions!</td>', 'LOL!  Gotta love those expressions!', '2012-08-30 01:05:02.000000', NULL, 1),
(6852113, 1031261, 30982, '<td valign="top">Nice collection of hats and smiles and not-smiles.</td>', 'Nice collection of hats and smiles and not-smiles.', '2012-08-30 01:05:23.000000', NULL, 1),
(6852114, 1031061, 30982, '<td valign="top">Almost has a frat house feel with a cinematic overlay in Miami....</td>', 'Almost has a frat house feel with a cinematic overlay in Miami....', '2012-08-30 01:05:46.000000', NULL, 1),
(6852115, 1031160, 30982, '<td valign="top">A good street portrait.</td>', 'A good street portrait.', '2012-08-30 01:05:58.000000', NULL, 1),
(6852116, 1031284, 30982, '<td valign="top">Nice use of the umbrella as a framing tool.</td>', 'Nice use of the umbrella as a framing tool.', '2012-08-30 01:06:17.000000', NULL, 1),
(6852118, 1030809, 30982, '<td valign="top">You got caught!  Interesting tidbit - they''re both wearing nice Nikes.</td>', 'You got caught!  Interesting tidbit - they''re both wearing nice Nikes.', '2012-08-30 01:07:00.000000', NULL, 1),
(6852119, 1031281, 30982, '<td valign="top">She reminds me of the daughter of a friend.  Has a time gone by kinda feel to it.</td>', 'She reminds me of the daughter of a friend.  Has a time gone by kinda feel to it.', '2012-08-30 01:07:35.000000', NULL, 1),
(6852120, 1031300, 30982, '<td valign="top">Maybe a bit of an opportunistic snap, so framing could be a bit better - the arm in the foreground, for instance, doesn''t add anything in my opinion.</td>', 'Maybe a bit of an opportunistic snap, so framing could be a bit better - the arm in the foreground, for instance, doesn''t add anything in my opinion.', '2012-08-30 01:08:27.000000', NULL, 1),
(6852121, 1031272, 30982, '<td valign="top">Interesting action, but I''d have liked a bit more of the people there.</td>', 'Interesting action, but I''d have liked a bit more of the people there.', '2012-08-30 01:08:52.000000', NULL, 1),
(6852122, 1031295, 30982, '<td valign="top">Feels a bit caught in time - as in trapped.  His real person seems so inert - his reflection so much more animated.</td>', 'Feels a bit caught in time - as in trapped.  His real person seems so inert - his reflection so much more animated.', '2012-08-30 01:09:39.000000', NULL, 1),
(6852123, 1031200, 30982, '<td valign="top">Nice use of the backdrop to provide a strong graphical feel.</td>', 'Nice use of the backdrop to provide a strong graphical feel.', '2012-08-30 01:09:59.000000', NULL, 1),
(6852124, 1031120, 30982, '<td valign="top">One of the things I like to do - shoot people shooting other people.  A wedding perhaps?</td>', 'One of the things I like to do - shoot people shooting other people.  A wedding perhaps?', '2012-08-30 01:10:40.000000', NULL, 1),
(6852126, 1031268, 30982, '<td valign="top">Interesting use of glow - not entirely sure I''m sold on it, but I do like the way it makes the steps seem more significant than the tiny soul sitting on them.</td>', 'Interesting use of glow - not entirely sure I''m sold on it, but I do like the way it makes the steps seem more significant than the tiny soul sitting on them.', '2012-08-30 01:11:51.000000', NULL, 1),
(6852128, 1031171, 30982, '<td valign="top">The overall softness seems to suit this as in a way, it feels damp and lush because of it.</td>', 'The overall softness seems to suit this as in a way, it feels damp and lush because of it.', '2012-08-30 01:12:25.000000', NULL, 1),
(6852130, 1030878, 30982, '<td valign="top">Indeed, a wonderful shaft of light.  It serves to isolate her well - seems she''s had a bit of a hard day.  I do wonder what this would be like in B&amp;W.</td>', 'Indeed, a wonderful shaft of light.  It serves to isolate her well - seems she''s had a bit of a hard day.  I do wonder what this would be like in B&W.', '2012-08-30 01:14:43.000000', NULL, 1),
(6852131, 1031023, 30982, '<td valign="top">Lively and energetic!</td>', 'Lively and energetic!', '2012-08-30 01:14:52.000000', NULL, 1),
(6852132, 1030967, 30982, '<td valign="top">An interesting composition - feels a bit uneasy (I want more on the right side) but provides fun things to investigate just the same.</td>', 'An interesting composition - feels a bit uneasy (I want more on the right side) but provides fun things to investigate just the same.', '2012-08-30 01:15:48.000000', NULL, 1),
(6852133, 1031139, 30982, '<td valign="top">Very colorful and sad at the same time.  Excellent light.</td>', 'Very colorful and sad at the same time.  Excellent light.', '2012-08-30 01:16:18.000000', NULL, 1),
(6852134, 1030995, 30982, '<td valign="top">They seem a bit worn out, don''t they?  Great backdrop.</td>', 'They seem a bit worn out, don''t they?  Great backdrop.', '2012-08-30 01:16:46.000000', NULL, 1),
(6852135, 1031181, 30982, '<td valign="top">Intersting curlique artifacts in the dark sections.  I like the fisheye view.</td>', 'Intersting curlique artifacts in the dark sections.  I like the fisheye view.', '2012-08-30 01:17:14.000000', NULL, 1),
(6852136, 1030676, 30982, '<td valign="top">A nice natural smile.  But dark chocolate linguine?  Not sure that sounds good.  Pasta and chocolate are not things I''d think go together...</td>', 'A nice natural smile.  But dark chocolate linguine?  Not sure that sounds good.  Pasta and chocolate are not things I''d think go together...', '2012-08-30 01:17:52.000000', NULL, 1),
(6852137, 1031125, 30982, '<td valign="top">A pet pigeon!  Gotta love it!</td>', 'A pet pigeon!  Gotta love it!', '2012-08-30 01:18:16.000000', NULL, 1),
(6852138, 1031006, 30982, '<td valign="top">I like how they both have the same lean going on here.  Well seen, good composition!</td>', 'I like how they both have the same lean going on here.  Well seen, good composition!', '2012-08-30 01:20:26.000000', NULL, 1),
(6852139, 1030580, 30982, '<td valign="top">One of the most authentic in the challenge - has a sense of downtrodden solitude to it.</td>', 'One of the most authentic in the challenge - has a sense of downtrodden solitude to it.', '2012-08-30 01:21:01.000000', NULL, 1),
(6852140, 1031013, 30982, '<td valign="top">A good tourist shot!</td>', 'A good tourist shot!', '2012-08-30 01:21:15.000000', NULL, 1),
(6852141, 1031041, 30982, '<td valign="top">The, um, location of the gun is most interesting... So is the relfective nature of the young lady''s glasses, and the word "RIBS" on the window behind her.  A fun catch.</td>', 'The, um, location of the gun is most interesting... So is the relfective nature of the young lady''s glasses, and the word "RIBS" on the window behind her.  A fun catch.', '2012-08-30 01:22:05.000000', NULL, 1),
(6852142, 1031084, 30982, '<td valign="top">Very nice depiction of a summer''s evening.  The comic-like processing brings out the detail nicely but may not suit some''s taste for "street" work.</td>', 'Very nice depiction of a summer''s evening.  The comic-like processing brings out the detail nicely but may not suit some''s taste for "street" work.', '2012-08-30 01:23:57.000000', NULL, 1),
(6852143, 1030944, 30982, '<td valign="top">The best part is the young lady laughing.</td>', 'The best part is the young lady laughing.', '2012-08-30 01:24:24.000000', NULL, 1),
(6852144, 1031229, 30982, '<td valign="top">Over the top processing but gotta love the guy''s pose as it seems a reverse to that of the elephant.</td>', 'Over the top processing but gotta love the guy''s pose as it seems a reverse to that of the elephant.', '2012-08-30 01:25:04.000000', NULL, 1),
(6852146, 1031279, 30982, '<td valign="top">LOVE the street light in the puddle.  Nice catch.</td>', 'LOVE the street light in the puddle.  Nice catch.', '2012-08-30 01:25:25.000000', NULL, 1),
(6852169, 1031177, 28742, '<td valign="top">"Look at dat missus Jones ober derr, mon, tinkin she''s all dat! Her grass ain''t no greener dan mine, mon." *sorry if my Jamaican accent is a little rusty. ...even sorrier if this is Chicago. ;-)</td>', '"Look at dat missus Jones ober derr, mon, tinkin she''s all dat! Her grass ain''t no greener dan mine, mon." *sorry if my Jamaican accent is a little rusty. ...even sorrier if this is Chicago. ;-)', '2012-08-30 03:47:45.000000', NULL, 1),
(6852171, 1031125, 28742, '<td valign="top">I must admit I am slightly hobophobic myself. ;-)</td>', 'I must admit I am slightly hobophobic myself. ;-)', '2012-08-30 04:04:22.000000', NULL, 1),
(6852174, 1031282, 28742, '<td valign="top">stalker/victim ;-)</td>', 'stalker/victim ;-)', '2012-08-30 04:07:52.000000', NULL, 1),
(6852175, 1031202, 28742, '<td valign="top">BW... really?</td>', 'BW... really?', '2012-08-30 04:09:14.000000', NULL, 1),
(6852176, 1031178, 28742, '<td valign="top">I''d give this an 8 if you aimed lower and didn''t cut off his feet.</td>', 'I''d give this an 8 if you aimed lower and didn''t cut off his feet.', '2012-08-30 04:12:24.000000', NULL, 1),
(6852179, 1031287, 28742, '<td valign="top">I am at 76/104 and this is the best so far. Love it! Top five if not a ribbon.</td>', 'I am at 76/104 and this is the best so far. Love it! Top five if not a ribbon.', '2012-08-30 04:14:23.000000', NULL, 1),
(6852182, 1031086, 28742, '<td valign="top">I could sit here all night and make up the conversation! :) Great capture - this is what it''s all about, IMO. One of my top picks and I am 86% through voting.</td>', 'I could sit here all night and make up the conversation! :) Great capture - this is what it''s all about, IMO. One of my top picks and I am 86% through voting.', '2012-08-30 04:18:18.000000', NULL, 1),
(6852183, 1031168, 28742, '<td valign="top">You kept the color where it should be kept - a rare good use of selective desat! :)</td>', 'You kept the color where it should be kept - a rare good use of selective desat! :)', '2012-08-30 04:19:58.000000', NULL, 1),
(6852184, 1031130, 28742, '<td valign="top">..........Ohhhh "THANK You" - at first I thought the headline said something else. ;-) LOVE the kid! Great capture.<br/> <br/>...bumping up to a 9</td>', '..........Ohhhh "THANK You" - at first I thought the headline said something else. ;-) LOVE the kid! Great capture. ...bumping up to a 9', '2012-08-30 04:22:55.000000', NULL, 1),
(6852185, 1031084, 28742, '<td valign="top">For me, shooting his back instead of his front took you from a likely 10 to a 7. Still a good image, though.</td>', 'For me, shooting his back instead of his front took you from a likely 10 to a 7. Still a good image, though.', '2012-08-30 04:24:02.000000', NULL, 1),
(6852186, 1031197, 113156, '<td valign="top">Fabulous catch.</td>', 'Fabulous catch.', '2012-08-30 04:25:47.000000', NULL, 1),
(6852189, 1030944, 28742, '<td valign="top">Priceless! I''m taking a picture of me taking a picture of this on my screen right now!<br/> <br/>...<a href="//www.dpchallenge.com/image.php?IMAGE_ID=1031755" rel="nofollow" target="_blank">see, I wasn''t kidding</a>. ;-)</td>', 'Priceless! I''m taking a picture of me taking a picture of this on my screen right now! ...see, I wasn''t kidding. ;-)', '2012-08-30 04:46:54.000000', NULL, 1),
(6852199, 1031279, 48963, '<td valign="top">I love this one, definitely one of my favorites so far!</td>', 'I love this one, definitely one of my favorites so far!', '2012-08-30 05:36:52.000000', NULL, 1),
(6852209, 1031217, 23484, '<td valign="top">Watch out for that tequila.</td>', 'Watch out for that tequila.', '2012-08-30 06:13:25.000000', NULL, 1),
(6852210, 1031138, 23484, '<td valign="top">The processing on this is outstanding.</td>', 'The processing on this is outstanding.', '2012-08-30 06:14:07.000000', NULL, 1),
(6852211, 1030785, 23484, '<td valign="top">Very nice image and great color.</td>', 'Very nice image and great color.', '2012-08-30 06:16:50.000000', NULL, 1),
(6852212, 1031086, 23484, '<td valign="top">Great. Wonderful shot of street life.</td>', 'Great. Wonderful shot of street life.', '2012-08-30 06:18:03.000000', NULL, 1),
(6852214, 1030844, 93565, '<td valign="top">Great collection of people, great composition. Very nicely done.</td>', 'Great collection of people, great composition. Very nicely done.', '2012-08-30 06:41:47.000000', NULL, 1),
(6852215, 1031013, 93565, '<td valign="top">Street photography succeeds when we feel as though we''re there, a part of it. This is a timid voyeur''s view, the view of somebody who is not part of the scene and hiding on the fringes.<br/>It also feels like the end of the action.</td>', 'Street photography succeeds when we feel as though we''re there, a part of it. This is a timid voyeur''s view, the view of somebody who is not part of the scene and hiding on the fringes.It also feels like the end of the action.', '2012-08-30 06:44:51.000000', NULL, 1),
(6852217, 1031158, 93565, '<td valign="top">The random heads obscure all attempts at story telling and the viewer''s yearning to feel a part of the scene.</td>', 'The random heads obscure all attempts at story telling and the viewer''s yearning to feel a part of the scene.', '2012-08-30 06:46:01.000000', NULL, 1),
(6852218, 1031082, 93565, '<td valign="top">I like your composition quite a bit. It''s interesting how disinterested everybody always is in public transport, like there is a tangible wall between them. One of my faves in this one.</td>', 'I like your composition quite a bit. It''s interesting how disinterested everybody always is in public transport, like there is a tangible wall between them. One of my faves in this one.', '2012-08-30 06:49:34.000000', NULL, 1),
(6852219, 1031229, 93565, '<td valign="top">Overdone- major halo''s on the buildings.</td>', 'Overdone- major halo''s on the buildings.', '2012-08-30 06:50:24.000000', NULL, 1),
(6852220, 1031266, 93565, '<td valign="top">The person with the cellphone is taking a much more intimate approach to this shot than the shooter.</td>', 'The person with the cellphone is taking a much more intimate approach to this shot than the shooter.', '2012-08-30 06:52:17.000000', NULL, 1),
(6852221, 1030674, 93565, '<td valign="top">Very cool scene, but I''d have preferred a bit more interest added from the person.</td>', 'Very cool scene, but I''d have preferred a bit more interest added from the person.', '2012-08-30 06:53:06.000000', NULL, 1),
(6852222, 1030785, 16241, '<td valign="top">az?</td>', 'az?', '2012-08-30 06:53:34.000000', NULL, 1),
(6852223, 1031139, 93565, '<td valign="top">This is a cool photo, but not quite sure on the fit to the challenge.</td>', 'This is a cool photo, but not quite sure on the fit to the challenge.', '2012-08-30 06:55:09.000000', NULL, 1),
(6852224, 1031261, 93565, '<td valign="top">Nicely seen with the billboards.</td>', 'Nicely seen with the billboards.', '2012-08-30 06:55:37.000000', NULL, 1),
(6852225, 1031131, 93565, '<td valign="top">I think this could''ve been awesome if you zoomed in more and dropped your perspective so the faces of the mother and child dominated with the scale between them.</td>', 'I think this could''ve been awesome if you zoomed in more and dropped your perspective so the faces of the mother and child dominated with the scale between them.', '2012-08-30 06:57:40.000000', NULL, 1),
(6852227, 1031004, 93565, '<td valign="top">Really not a fan of the border on this one, but it''s not particularly fetching so far as the prompt goes, either.</td>', 'Really not a fan of the border on this one, but it''s not particularly fetching so far as the prompt goes, either.', '2012-08-30 07:03:39.000000', NULL, 1),
(6852228, 1031086, 93565, '<td valign="top">Nice composition with the three groups. Unless I''m wrong, the dodging of the folks in the shadows makes them look a bit too bright compared to how I''d think they''d be rendered. It work well though, and the line of the shadow itself pulls the viewer through things well. Nice timing with the gesturing and the open mouth. Feels <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_N.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_N.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_N.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=113156" rel="nofollow" target="_blank">jagar</a>y.</td>', 'Nice composition with the three groups. Unless I''m wrong, the dodging of the folks in the shadows makes them look a bit too bright compared to how I''d think they''d be rendered. It work well though, and the line of the shadow itself pulls the viewer through things well. Nice timing with the gesturing and the open mouth. Feels  jagary.', '2012-08-30 07:06:54.000000', NULL, 1),
(6852231, 1031222, 93565, '<td valign="top">The ostentatious cross necklace works great here.<br/> <br/>Came back to bump up. Tied for my fave in the challenge.</td>', 'The ostentatious cross necklace works great here. Came back to bump up. Tied for my fave in the challenge.', '2012-08-30 07:24:36.000000', NULL, 1),
(6852232, 1031177, 93565, '<td valign="top">Killer expressions and postures. Great one in this.<br/> <br/>Came back to bump. 3 way tie for my favorite in the challenge.</td>', 'Killer expressions and postures. Great one in this. Came back to bump. 3 way tie for my favorite in the challenge.', '2012-08-30 07:24:57.000000', NULL, 1),
(6852345, 1031197, 54778, '<td valign="top">Love the energy of this shot!!</td>', 'Love the energy of this shot!!', '2012-08-30 10:17:14.000000', NULL, 1),
(6852346, 1030674, 54778, '<td valign="top">Great use of colours and I really like the shadow play on the street</td>', 'Great use of colours and I really like the shadow play on the street', '2012-08-30 10:18:09.000000', NULL, 1),
(6852368, 1030676, 19825, '<td valign="top">Nice candid street portrait and interesting setting. Dark Chocolate Linguine?</td>', 'Nice candid street portrait and interesting setting. Dark Chocolate Linguine?', '2012-08-30 11:17:36.000000', NULL, 1),
