(6852371, 1030674, 112739, '<td valign="top">Works very well. The walker''s shadow adds another element to the already interesting composition and story.</td>', 'Works very well. The walker''s shadow adds another element to the already interesting composition and story.', '2012-08-30 11:38:46.000000', NULL, 1),
(6852373, 1031006, 112739, '<td valign="top">Nicely caught. I like the processing as well.</td>', 'Nicely caught. I like the processing as well.', '2012-08-30 11:41:53.000000', NULL, 1),
