(6852432, 1031229, 12611, '<td valign="top">Great colors. and the Mister Bean style fellow walking through makes it interesting.</td>', 'Great colors. and the Mister Bean style fellow walking through makes it interesting.', '2012-08-30 12:56:24.000000', NULL, 1),
