(6853521, 1031159, 12611, '<td valign="top">Those eyes have seen too much, not enough.</td>', 'Those eyes have seen too much, not enough.', '2012-08-31 22:36:33.000000', NULL, 1),
(6853522, 1030580, 12611, '<td valign="top">The shot says a great deal about the photographer. In the action, in control, but not up front and center, reflective, enlightening.</td>', 'The shot says a great deal about the photographer. In the action, in control, but not up front and center, reflective, enlightening.', '2012-08-31 22:37:47.000000', NULL, 1),
