(6853963, 1030788, 142473, '<td valign="top">Interesting processing, but I do not understand the message.  The lighting is a bit flat, except on one person, and ends up almost emphasizing her instead.</td>', 'Interesting processing, but I do not understand the message.  The lighting is a bit flat, except on one person, and ends up almost emphasizing her instead.', '2012-09-01 16:41:37.000000', NULL, 1),
(6853965, 1031279, 142473, '<td valign="top">Are pregnant women allowed to dance?<br/> <br/>Kudos for having no motion blur on a night shot like this.  I do like the composition.</td>', 'Are pregnant women allowed to dance? Kudos for having no motion blur on a night shot like this.  I do like the composition.', '2012-09-01 16:43:41.000000', NULL, 1),
(6853966, 1030878, 142473, '<td valign="top">Yes, quite spectacular light.  I might have tried desaturating or darkening the rest of the shot even more..  No desat needed on her face though.  Great expression.</td>', 'Yes, quite spectacular light.  I might have tried desaturating or darkening the rest of the shot even more..  No desat needed on her face though.  Great expression.', '2012-09-01 16:45:26.000000', NULL, 1),
