(6854867, 1031184, 54645, '<td valign="top">Ha! Great scene. The dogs mask is off, abut it is a fun photograph nonetheless.</td>', 'Ha! Great scene. The dogs mask is off, abut it is a fun photograph nonetheless.', '2012-09-03 00:45:32.000000', NULL, 1),
