(6859422, 1030844, 68020, '<td valign="top">Still love this shot George...Everyone carrying life''s burdens. Three totally different stories.</td>', 'Still love this shot George...Everyone carrying life''s burdens. Three totally different stories.', '2012-09-07 15:59:22.000000', NULL, 0),
(6859751, 1031041, 30982, '<td valign="top">This still cracks me up.</td>', 'This still cracks me up.', '2012-09-07 23:18:34.000000', NULL, 0),
(6860220, 1030844, 76335, '<td valign="top">Thanks for the mention. This one worked for me. I''ve been known to shadow people for blocks if they''re carrying something interesting. What I find especially striking about this shot is that your subjects seem privy to your plan -- the knowing smiles and very deliberate strides. A success, I''d say.</td>', 'Thanks for the mention. This one worked for me. I''ve been known to shadow people for blocks if they''re carrying something interesting. What I find especially striking about this shot is that your subjects seem privy to your plan -- the knowing smiles and very deliberate strides. A success, I''d say.', '2012-09-08 16:43:14.000000', NULL, 0),
(6860347, 1031302, 23484, '<td valign="top">What a great street shot. The wet pavement is wonderful.</td>', 'What a great street shot. The wet pavement is wonderful.', '2012-09-08 21:57:25.000000', NULL, 0),
(6860349, 1031133, 23484, '<td valign="top">go to the light!</td>', 'go to the light!', '2012-09-08 22:00:03.000000', NULL, 0),
(6865422, 1031006, 112972, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Aperture_Ready:</b></div><hr/><i>Can i asked what processing you used for this image ..its lovely </i></td></tr></table> <br/> <br/>Thanks!  It''s mostly adding contrast and doing some dodge and burn in order to draw the eye to the main subjects.</td>', 'Originally posted by Aperture_Ready:Can i asked what processing you used for this image ..its lovely   Thanks!  It''s mostly adding contrast and doing some dodge and burn in order to draw the eye to the main subjects.', '2012-09-18 16:10:00.000000', NULL, 0),
